from collections import deque


def hopcroft_karp(left_n, right_m, adj):
    """Hopcroft-Karp 求二分图最大匹配，O(E√V)。
    adj[u]: 左部点 u 的右部点邻居列表。返回 (匹配数, pairU, pairV)。"""
    pairU = [-1] * left_n
    pairV = [-1] * right_m
    NIL = left_n
    dist = [-1] * (left_n + 1)

    def bfs():
        q = deque()
        found = False
        for u in range(left_n):
            if pairU[u] == -1:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = -1
        dist[NIL] = -1
        while q:
            u = q.popleft()
            for v in adj[u]:
                w = pairV[v]
                if w == -1:
                    found = True
                elif dist[w] == -1:
                    dist[w] = dist[u] + 1
                    q.append(w)
        return found

    def dfs(u):
        for v in adj[u]:
            w = pairV[v]
            if w == -1 or (dist[w] == dist[u] + 1 and dfs(w)):
                pairU[u] = v
                pairV[v] = u
                return True
        dist[u] = -1
        return False

    res = 0
    while bfs():
        for u in range(left_n):
            if pairU[u] == -1 and dfs(u):
                res += 1
    return res, pairU, pairV


