    import random

    def kuhn(n, m, adj):
        match = [-1] * m

        def tr(u, vis):
            for v in adj[u]:
                if vis[v]:
                    continue
                vis[v] = True
                if match[v] == -1 or tr(match[v], vis):
                    match[v] = u
                    return True
            return False

        r = 0
        for u in range(n):
            if tr(u, [False] * m):
                r += 1
        return r

    random.seed(5)
    for _ in range(200):
        n = random.randint(1, 20)
        m = random.randint(1, 20)
        adj = [[] for _ in range(n)]
        for u in range(n):
            for v in range(m):
                if random.random() < 0.25:
                    adj[u].append(v)
        r1, _, _ = hopcroft_karp(n, m, adj)
        r2 = kuhn(n, m, adj)
        assert r1 == r2, (n, m, adj, r1, r2)
